/// Authority is the lease's published validity evaluated at ask time on
/// the monotonic clock — not the `Held` variant. A peer treats the record
/// as dead the instant `now_ms` reaches `expires_ms`, so a holder whose
/// lease lapsed must answer `false` here even if `Timer::NodeLeaseFence`
/// has not fired yet: the timer is the liveness backstop that halts the
/// process, never the safety mechanism. A suspended VM's timer fires
/// late, but a request evaluated after resume still refuses. The `<` /
/// `>=` polarity matches the fence timer at `handle_timer`, so the
/// predicate and the timer cannot disagree.
pub fn node_authoritative(&self) -> bool {
    if !self.config.require_node_lease {
        return !self.fenced;
    }
    let fresh = |held: &HeldNodeLease| {
        self.now_mono_ms.saturating_sub(held.last_ok_mono_ms) < held.spec.ttl_ms
    };
    match &self.node_authority {
        NodeAuthority::Held(held) => fresh(held),
        NodeAuthority::Reading { pending, .. } | NodeAuthority::Writing { pending, .. } => {
            pending.prior.as_ref().is_some_and(fresh)
        }
        _ => false,
    }
}

/// Each follower session uses `<root>/peerlog/<node>/<generation>/`. The store
/// persists the seal mark before it sends the response, so the mark survives a
/// follower restart. The store also reads the former flat layout during an
/// upgrade.
pub struct FollowerStore {
    root: PathBuf,
    filesystem: Arc<dyn celld_ltx::FileSystem>,
    bucket: Option<Arc<Bucket>>,
    node: String,
    logs: Mutex<HashMap<String, FollowerState>>,
    /// Per-leader mutual exclusion over the whole read-modify-write of a
    /// fragment. Without it, an append that loaded state before a seal
    /// persists writes the stale `sealed_to` back afterwards — the seal
    /// mark is atomic in the model and must be atomic here.
    guards: Mutex<HashMap<String, Arc<tokio::sync::Mutex<()>>>>,
    /// Leaders whose directory chain this process has already fsynced to
    /// the data root. Ancestor directory entries only change when the
    /// leader directory is created, so re-syncing them on every state
    /// persist was one serial fsync chain per append — the write-latency
    /// floor the 2026-08-25 gate decomposition landed on. A restart
    /// starts empty and conservatively re-syncs each chain once.
    synced_namespaces: Mutex<std::collections::BTreeSet<String>>,
    #[cfg(celld_internal_tests)]
    directory_sync_for_test: Arc<DirectorySyncForTest>,
}

impl FollowerStore {
    /// The takeover interlock, as a core decision (lease-fold): the dead
    /// owner's folded log state was not sealed, so its acked tail may
    /// exist only on its followers. The executor recovers every
    /// non-sealed session of `owner` into the bucket and reports
    /// `NodeLogRecovered`; only then does the claim proceed.
    RecoverNodeLog {
